Build a room_bookings table where the database itself prevents two overlapping bookings for the same room. Prove it by attempting an overlapping insert.
Solution
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE room_bookings (
id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
room_id bigint NOT NULL,
during tstzrange NOT NULL,
EXCLUDE USING gist (room_id WITH =, during WITH &&)
);
INSERT INTO room_bookings (room_id, during)
VALUES (1, '[2026-06-02 09:00, 2026-06-02 11:00)');
INSERT INTO room_bookings (room_id, during)
VALUES (1, '[2026-06-02 10:00, 2026-06-02 12:00)');
-- ERROR: conflicting key value violates exclusion constraint "room_bookings_room_id_during_excl"
